Object.assign(SNIP,{"l28gian": "// thêm x vào cuối mảng động a (đang có n phần tử, sức chứa cap)\nvoid them(int*& a, int& n, int& cap, int x) {\n    if (n == cap) {                    // hết chỗ: xin khối mới gấp đôi\n        int* moi = new int[cap * 2];\n        for (int i = 0; i < n; i++) moi[i] = a[i];\n        delete[] a;                    // trả khối cũ\n        a = moi;\n        cap *= 2;\n    }\n    a[n] = x;\n    n++;\n}", "l28cu": "int* p = new int;          // một ô int trên heap, giá trị chưa xác định\nint* q = new int(7);       // một ô int, khởi tạo bằng 7\nint* a = new int[n];       // n ô int liền nhau (n có thể nhập lúc chạy)\n\ndelete p;                  // trả một ô\ndelete q;\ndelete[] a;                // trả cả mảng: new[] đi với delete[]\np = nullptr;               // thói quen tốt: con trỏ đã trả thì gán nullptr", "l28mat": "int** m = new int*[h];             // h con trỏ, mỗi cái sẽ trỏ tới một hàng\nfor (int i = 0; i < h; i++) m[i] = new int[w];\nm[i][j] = 5;                       // dùng như mảng hai chiều\nfor (int i = 0; i < h; i++) delete[] m[i];   // trả từng hàng trước\ndelete[] m;                                   // rồi mới trả mảng con trỏ"});PRESET_NOTES["l28"]={"Ví dụ: Một ô trên heap": "new int(7) tạo khối #1 trên heap và p giữ địa chỉ của nó. Sau delete p, khối được đánh dấu đã trả; gán p = nullptr để không ai dùng nhầm địa chỉ cũ. Lệnh delete p thứ hai an toàn vì p đang là nullptr.", "Ví dụ: Mảng động new[] và delete[]": "n được nhập lúc chạy nên mảng phải xin trên heap. Khối #1 có đúng n ô liền nhau, địa chỉ cách nhau 4 byte. Xin bằng new[] nên trả bằng delete[].", "Ví dụ: Mảng tự giãn gấp đôi": "Sức chứa đi 1 → 2 → 4 → 8. Mỗi lần đầy, một khối mới gấp đôi xuất hiện trên heap, dữ liệu được chép sang và khối cũ mờ đi (đã delete). a là tham chiếu tới con trỏ của main (int*&) nên main nhận được địa chỉ khối mới.", "Ví dụ: Ma trận động int**": "Khối #1 là mảng 2 con trỏ; mỗi con trỏ chỉ tới một hàng (khối #2, #3) nằm riêng trên heap. Mũi tên cho thấy các hàng không nhất thiết nằm sát nhau. Trả các hàng trước, rồi mới trả khối #1.", "Lỗi: xin bằng new[] nhưng trả bằng delete": "a được cấp bằng new[] nên phải trả bằng delete[]. g++ cảnh báo -Wmismatched-new-delete; với các kiểu có hàm hủy (học ở chương lớp), lỗi này làm hỏng chương trình. Sửa: delete[] a;.", "Lỗi: delete hai lần qua hai con trỏ": "p và q cùng trỏ vào khối #1. delete p trả khối; delete q trả lại chính khối đó lần nữa và chương trình bị hủy với free(): double free detected. Một khối chỉ có một chủ: sau delete p, gán p = nullptr và không dùng q nữa."};EX_HINTS["l28"]=[["Phải đọc hết dãy mới biết trung bình, rồi duyệt lại lần hai: đó là lý do cần lưu mảng.", "So sánh a[i] > tong / n bằng số nguyên cho chắc: a[i] * n > tong (đổi sang long long trước khi nhân)."], ["Nếu chưa xử lý trường hợp đầy, a[n] = x sẽ ghi ra ngoài khối và trình mô phỏng báo lỗi.", "Thứ tự: xin khối mới, chép n phần tử, delete[] khối cũ, rồi mới gán a = moi (a là int*& nên main thấy địa chỉ mới)."], ["t có w hàng: new int*[w], mỗi hàng t[j] = new int[h].", "Trả theo thứ tự ngược với lúc xin: các hàng trước, mảng con trỏ sau. Làm cho cả a và t."]];
