/* Bài 28 · new / delete
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P28=[{label:"Ví dụ: Một ô trên heap",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int* p = new int(7);\n    cout << *p << \"\\n\";\n    *p += 3;\n    cout << *p << \"\\n\";\n    delete p;\n    p = nullptr;\n    delete p;\n    cout << \"Xong\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Mảng động new[] và delete[]",input:"5",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int* a = new int[n];\n    for (int i = 0; i < n; i++) {\n        a[i] = i * i;\n    }\n    for (int i = 0; i < n; i++) cout << a[i] << \" \";\n    cout << \"\\n\";\n    delete[] a;\n    a = nullptr;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Mảng tự giãn gấp đôi",input:"",code:"#include <iostream>\nusing namespace std;\n\nvoid them(int*& a, int& n, int& cap, int x) {\n    if (n == cap) {\n        int* moi = new int[cap * 2];\n        for (int i = 0; i < n; i++) moi[i] = a[i];\n        delete[] a;\n        a = moi;\n        cap *= 2;\n    }\n    a[n] = x;\n    n++;\n}\n\nint main() {\n    int n = 0, cap = 1;\n    int* a = new int[cap];\n    for (int x = 10; x <= 50; x += 10) {\n        them(a, n, cap, x);\n    }\n    cout << n << \" phan tu, suc chua \" << cap << \"\\n\";\n    delete[] a;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Ma trận động int**",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int h = 2, w = 3;\n    int** m = new int*[h];\n    for (int i = 0; i < h; i++) {\n        m[i] = new int[w];\n        for (int j = 0; j < w; j++) m[i][j] = i * w + j;\n    }\n    cout << m[1][2] << \"\\n\";\n    for (int i = 0; i < h; i++) delete[] m[i];\n    delete[] m;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: xin bằng new[] nhưng trả bằng delete",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int* a = new int[4];\n    for (int i = 0; i < 4; i++) a[i] = i;\n    cout << a[3] << \"\\n\";\n    delete a;\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: delete hai lần qua hai con trỏ",input:"",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int* p = new int(5);\n    int* q = p;\n    cout << *q << \"\\n\";\n    delete p;\n    delete q;\n    return 0;\n}",viz:[{type:"mem"}]}];
const sim28=makeSim2(document.getElementById("sim-l28"),{id:"s28",presets:P28});
makeEx2(document.getElementById("ex-l28"),sim28,[{t:"Bao nhiêu số lớn hơn trung bình",d:"Nhập n (1 ≤ n ≤ 10<sup>5<\/sup>) rồi n số nguyên (|x| ≤ 10<sup>9<\/sup>). Lưu vào mảng xin bằng <code>new int[n]<\/code>, in số phần tử lớn hơn trung bình cộng, rồi trả mảng.",tests:[{in:"5\n1 2 3 4 10",out:"1"},{in:"4\n5 5 5 5",out:"0"},{in:"3\n-3 0 3",out:"1"},{in:"6\n1000000000 1000000000 -1000000000 7 8 9",out:"2"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    // xin mảng, đọc dữ liệu, tính tổng (long long), đếm, rồi delete[]\n    return 0;\n}",need:/new\s+int\s*\[[\s\S]*delete\s*\[\s*\]/,needMsg:"Hãy lưu dãy trong mảng xin bằng new int[n] và trả bằng delete[]."},{t:"Tự cài push_back",d:"Nhập n (1 ≤ n ≤ 1000) rồi n số nguyên. Bắt đầu với mảng động sức chứa 1. Viết hàm <code>void them(int*&amp; a, int&amp; n, int&amp; cap, int x)<\/code>: khi đầy thì xin khối gấp đôi, chép sang, trả khối cũ. Thêm lần lượt các số rồi in: dòng 1 là số phần tử và sức chứa, dòng 2 là các phần tử.",tests:[{in:"5\n3 1 4 1 5",out:"5 8\n3 1 4 1 5"},{in:"1\n9",out:"1 1\n9"},{in:"4\n1 2 3 4",out:"4 4\n1 2 3 4"},{in:"9\n9 8 7 6 5 4 3 2 1",out:"9 16\n9 8 7 6 5 4 3 2 1"}],start:"#include <iostream>\nusing namespace std;\n\nvoid them(int*& a, int& n, int& cap, int x) {\n    // nếu n == cap: xin new int[cap * 2], chép, delete[] khối cũ, cập nhật a và cap\n    a[n] = x;\n    n++;\n}\n\nint main() {\n    int k;\n    cin >> k;\n    int n = 0, cap = 1;\n    int* a = new int[cap];\n    for (int i = 0; i < k; i++) {\n        int x;\n        cin >> x;\n        them(a, n, cap, x);\n    }\n    cout << n << \" \" << cap << \"\\n\";\n    for (int i = 0; i < n; i++) cout << a[i] << \" \";\n    cout << \"\\n\";\n    delete[] a;\n    return 0;\n}",need:/void\s+them\s*\(\s*int\s*\*\s*&\s*\w+[\s\S]*new\s+int\s*\[[\s\S]*delete\s*\[\s*\]/,needMsg:"Hãy giữ hàm void them(int*& a, ...) và trong đó xin khối mới bằng new int[...], trả khối cũ bằng delete[]."},{t:"Chuyển vị ma trận động",d:"Nhập h, w (1 ≤ h, w ≤ 100) rồi ma trận h × w. Tạo ma trận động <code>int** t<\/code> kích thước w × h với <code>t[j][i] = a[i][j]<\/code>, in t (mỗi hàng một dòng), rồi trả toàn bộ vùng nhớ.",tests:[{in:"2 3\n1 2 3\n4 5 6",out:"1 4\n2 5\n3 6"},{in:"1 1\n7",out:"7"},{in:"3 1\n1\n2\n3",out:"1 2 3"},{in:"2 2\n1 2\n3 4",out:"1 3\n2 4"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    int h, w;\n    cin >> h >> w;\n    int** a = new int*[h];\n    for (int i = 0; i < h; i++) {\n        a[i] = new int[w];\n        for (int j = 0; j < w; j++) cin >> a[i][j];\n    }\n    // tạo t gồm w hàng, mỗi hàng h phần tử; điền t[j][i] = a[i][j]; in t\n    // trả từng hàng rồi trả mảng con trỏ, cho cả a và t\n    return 0;\n}",need:/int\s*\*\s*\*\s*t\s*=\s*new\s+int\s*\*\s*\[[\s\S]*delete\s*\[\s*\]\s*t\s*;/,needMsg:"Hãy tạo int** t = new int*[w]; ... và kết thúc bằng delete[] t;."}]);

makeQuiz("quiz28","score28",[{"q": "Cặp nào ghép <b>đúng<\/b>?", "o": ["<code>new int[5]<\/code> với <code>delete<\/code>", "<code>new int(5)<\/code> với <code>delete[]<\/code>", "<code>new int[5]<\/code> với <code>delete[]<\/code>", "<code>new int<\/code> với <code>free<\/code>"], "a": 2, "e": "new[] đi với delete[], new đi với delete. Trộn lẫn là hành vi không xác định."}, {"q": "Sau <code>delete p;<\/code> thì p chứa gì?", "o": ["nullptr", "0", "Vẫn là địa chỉ cũ, nhưng không còn hợp lệ", "Giá trị của ô vừa trả"], "a": 2, "e": "delete chỉ trả vùng nhớ, không sửa p. Vì vậy nên gán p = nullptr ngay sau đó."}, {"q": "<code>int* p = nullptr; delete p;<\/code> thì sao?", "o": ["Lỗi biên dịch", "Chương trình bị dừng", "Không có gì xảy ra, hoàn toàn hợp lệ", "Rò rỉ bộ nhớ"], "a": 2, "e": "delete nullptr được chuẩn C++ bảo đảm là không làm gì."}, {"q": "Mảng tự giãn nhân đôi sức chứa khi đầy. Thêm lần lượt 9 phần tử, bắt đầu từ sức chứa 1, thì sức chứa cuối là?", "o": ["9", "10", "16", "18"], "a": 2, "e": "1 → 2 → 4 → 8 → 16: phần tử thứ 9 không vừa sức chứa 8 nên phải nhân đôi lên 16."}]);

